def f(g):
    import numpy as np
    a=np.array(g); out=a.copy(); H,W=a.shape
    def runs(idxs):
        res=[]; cur=[idxs[0]]
        for x in idxs[1:]:
            if x==cur[-1]+1: cur.append(x)
            else: res.append(cur); cur=[x]
        res.append(cur); return res
    def nz(v): return (np.array(v)!=0).any()
    for c in range(W):
        col=[r for r in range(H) if a[r,c]==5]
        if len(col)>=2:
            for rr in runs(col):
                if len(rr)<2 or c+1>=W: continue
                r0,r1=rr[0],rr[-1]
                rows=[r for r in range(H) if a[r,c+1]!=0]
                for end in (r1,r0):
                    grp=[r for r in rows if r0<=r<=r1]
                    if not (grp and end in grp): continue
                    lo=[r for r in grp if r<=end]; hi=[r for r in grp if r>=end]
                    b0,b1=(lo[0],lo[-1]) if end==r1 else (hi[0],hi[-1])
                    w=1
                    while c+1+w<W and nz(a[b0:b1+1,c+1+w]): w+=1
                    block=a[b0:b1+1,c+1:c+1+w]
                    n=b1-b0+1; L=len(rr); bh=b1-b0+1
                    if end==r1:
                        out[r0:r1+1,c+1:c+1+w]=np.tile(block,(L//bh+1,1))[-L:]
                    else:
                        out[r0:r1+1,c+1:c+1+w]=np.tile(block,(L//bh+1,1))[:L]
                    break
    for r in range(H):
        row=[c for c in range(W) if a[r,c]==5]
        if len(row)>=2:
            for cc in runs(row):
                if len(cc)<2 or r+1>=H: continue
                c0,c1=cc[0],cc[-1]
                cols=[c for c in range(W) if a[r+1,c]!=0]
                for end in (c0,c1):
                    grp=[c for c in cols if c0<=c<=c1]
                    if not (grp and end in grp): continue
                    lo=[c for c in grp if c<=end]; hi=[c for c in grp if c>=end]
                    b0,b1=(lo[0],lo[-1]) if end==c1 else (hi[0],hi[-1])
                    h=1
                    while r+1+h<H and nz(a[r+1:r+1+h+1,b0:b1+1]).all() and nz(a[r+1+h,b0:b1+1]): h+=1
                    block=a[r+1:r+1+h,b0:b1+1]
                    n=b1-b0+1; L=len(cc); bw=b1-b0+1
                    if end==c1:
                        out[r+1:r+1+h,c0:c1+1]=np.tile(block,(1,L//bw+1))[:,-L:]
                    else:
                        out[r+1:r+1+h,c0:c1+1]=np.tile(block,(1,L//bw+1))[:,:L]
                    break
    return out.tolist()
